576→// RestoreLogsOnly restores session logs from a logs-only rewind point.
577→// This fetches the transcript from entire/checkpoints/v1 and writes it to the agent's session directory.
578→// Does not modify the working directory.
579→// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
580→// If force is false, prompts for confirmation when local logs have newer timestamps.
581→// Returns info about each restored session so callers can print correct per-session resume commands.
582→func (s *ManualCommitStrategy) RestoreLogsOnly(ctx context.Context, point RewindPoint, force bool) ([]RestoredSession, error) {
583→	if !point.IsLogsOnly {
584→		return nil, errors.New("not a logs-only rewind point")
585→	}
586→
587→	if point.CheckpointID.IsEmpty() {
588→		return nil, errors.New("missing checkpoint ID")
589→	}
590→
591→	// Get checkpoint store
592→	store, err := s.getCheckpointStore()
593→	if err != nil {
594→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
595→	}
596→
597→	// Read checkpoint summary to get session count
598→	summary, err := store.ReadCommitted(ctx, point.CheckpointID)
599→	if err != nil {
600→		return nil, fmt.Errorf("failed to read checkpoint: %w", err)
601→	}
602→	if summary == nil {
603→		return nil, fmt.Errorf("checkpoint not found: %s", point.CheckpointID)
604→	}
605→
606→	// Get worktree root for agent session directory lookup
607→	repoRoot, err := paths.WorktreeRoot(ctx)
608→	if err != nil {
609→		return nil, fmt.Errorf("failed to get worktree root: %w", err)
610→	}
611→
612→	// Check for newer local logs if not forcing
613→	if !force {
614→		sessions := s.classifySessionsForRestore(ctx, repoRoot, store, point.CheckpointID, summary)
615→		hasConflicts := false
616→		for _, sess := range sessions {
617→			if sess.Status == StatusLocalNewer {
618→				hasConflicts = true
619→				break
620→			}
621→		}
622→		if hasConflicts {
623→			shouldOverwrite, promptErr := PromptOverwriteNewerLogs(sessions)
624→			if promptErr != nil {
625→				return nil, promptErr
626→			}
627→			if !shouldOverwrite {
628→				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session logs preserved.\n")
629→				return nil, nil
630→			}
631→		}
632→	}
633→
634→	// Count sessions to restore
635→	totalSessions := len(summary.Sessions)
636→	if totalSessions > 1 {
637→		fmt.Fprintf(os.Stderr, "Restoring %d sessions from checkpoint:\n", totalSessions)
638→	}
639→
640→	// Restore all sessions (oldest to newest, using 0-based indexing)
641→	var restored []RestoredSession
